text:
From the Fed to the front door
The policy rate is an overnight rate, whereas a standard U.S. mortgage fixes payments for 15 or 30 years. Mortgage pricing therefore reflects expected future short rates, longer-term Treasury yields, inflation expectations, mortgage-backed-security risk, and lender margins:
\[
r_t^{mortgage}
\approx
y_t^{10Y}+\text{MBS spread}_t.
\]
This distinction matters. The September decision can move expectations, but the same week’s mortgage-rate change cannot be attributed entirely to the announcement.
I used rvest to collect the FOMC statement, the Federal Reserve’s H.15 interest-rate table, Freddie Mac’s weekly Primary Mortgage Market Survey (PMMS), and the Census Bureau’s latest New Residential Sales release. The pages are public and require no login. Requests are rate-limited and cached locally.


Show the reproducible R code
fomc_page &lt;- read_cached_page(
  "https://www.federalreserve.gov/newsevents/pressreleases/monetary20260916a.htm",
  "fomc_2026-09-16.html"
)

fomc_text &lt;- fomc_page |&gt;
  html_elements("#article p") |&gt;
  html_text2() |&gt;
  str_c(collapse = " ")

stopifnot(str_detect(fomc_text, "3-3/4 to 4 percent"))

h15_page &lt;- read_cached_page(
  "https://www.federalreserve.gov/releases/h15/",
  "h15_2026-09-21.html"
)

h15 &lt;- h15_page |&gt;
  html_element("table") |&gt;
  html_table(fill = TRUE) |&gt;
  clean_names()

h15_long &lt;- h15 |&gt;
  pivot_longer(-instruments, names_to = "date_label", values_to = "rate") |&gt;
  mutate(
    date = date_label |&gt;
      str_remove("^x") |&gt;
      str_replace_all("_", " ") |&gt;
      parse_date_time("Y b d") |&gt;
      as_date(),
    rate = parse_number(as.character(rate)) / 100
  )

policy_snapshot &lt;- h15_long |&gt;
  filter(
    date %in% ymd(c("2026-09-16", "2026-09-17")),
    str_detect(instruments, "Federal funds \\(effective\\)|Bank prime loan")
  ) |&gt;
  mutate(
    series = if_else(
      str_detect(instruments, "Federal funds"),
      "Effective federal funds rate",
      "Bank prime rate"
    )
  ) |&gt;
  select(date, series, rate)

stopifnot(nrow(policy_snapshot) == 4)

pmms_page &lt;- read_cached_page(
  "https://www.freddiemac.com/pmms/archive",
  "pmms_2026-09-21.html"
)

pmms_dates &lt;- pmms_page |&gt;
  html_elements("p.lead strong") |&gt;
  html_text2() |&gt;
  mdy()

pmms_tables &lt;- pmms_page |&gt;
  html_elements("table.hover") |&gt;
  html_table(fill = TRUE)

stopifnot(length(pmms_dates) == length(pmms_tables))

pmms &lt;- map2_dfr(pmms_dates, pmms_tables, \(date, tab) {
  tab |&gt;
    clean_names() |&gt;
    transmute(
      date = date,
      mortgage_30y = percent_to_decimal(x30_yr_frm),
      mortgage_15y = percent_to_decimal(x15_yr_frm)
    )
}) |&gt;
  arrange(date)

census_page &lt;- read_cached_page(
  "https://www.census.gov/construction/nrs/current/index.html",
  "census_nrs_2026-09-21.html"
)

census_text &lt;- census_page |&gt;
  html_element("body") |&gt;
  html_text2()


median_price_match &lt;- str_match(
  census_text,
  regex(
    "median sales price[^$]+\\$([0-9,]+)",
    ignore_case = TRUE
  )
)

median_price &lt;- parse_number(
  median_price_match[1, 2]
)


analysis_rates &lt;- pmms |&gt;
  filter(date %in% ymd(c("2026-09-10", "2026-09-17")))

stopifnot(nrow(analysis_rates) == 2, !is.na(median_price))

rate_before &lt;- analysis_rates$mortgage_30y[1]
rate_after  &lt;- analysis_rates$mortgage_30y[2]
rate_change_bp &lt;- (rate_after - rate_before) * 10000

effr_before &lt;- policy_snapshot |&gt;
  filter(series == "Effective federal funds rate", date == ymd("2026-09-16")) |&gt;
  pull(rate)
effr_after &lt;- policy_snapshot |&gt;
  filter(series == "Effective federal funds rate", date == ymd("2026-09-17")) |&gt;
  pull(rate)
prime_before &lt;- policy_snapshot |&gt;
  filter(series == "Bank prime rate", date == ymd("2026-09-16")) |&gt;
  pull(rate)
prime_after &lt;- policy_snapshot |&gt;
  filter(series == "Bank prime rate", date == ymd("2026-09-17")) |&gt;
  pull(rate)

Data collection, cleaning, and validation


Show the reproducible R code
# FOMC statement ---------------------------------------------------------
fomc_page &lt;- read_cached_page(
  "https://www.federalreserve.gov/newsevents/pressreleases/monetary20260916a.htm",
  "fomc_2026-09-16.html"
)

fomc_text &lt;- fomc_page |&gt;
  html_elements("#article p") |&gt;
  html_text2() |&gt;
  str_squish() |&gt;
  str_c(collapse = " ")

if (!str_detect(fomc_text, "3-3/4 to 4 percent")) {
  stop("The expected target range was not found in the FOMC statement.")
}

# Federal Reserve H.15 --------------------------------------------------
h15_page &lt;- read_cached_page(
  "https://www.federalreserve.gov/releases/h15/",
  "h15_2026-09-21.html"
)

h15 &lt;- h15_page |&gt;
  html_element("table") |&gt;
  html_table(fill = TRUE) |&gt;
  clean_names()

h15_long &lt;- h15 |&gt;
  pivot_longer(
    -instruments,
    names_to = "date_label",
    values_to = "rate_text"
  ) |&gt;
  mutate(
    date_text = date_label |&gt;
      str_remove("^x") |&gt;
      str_replace_all("_", " "),
    date = parse_date_time(
      date_text,
      orders = "Y b d",
      locale = "C",
      quiet = TRUE
    ) |&gt;
      as_date(),
    rate = parse_number(as.character(rate_text)) / 100
  )

policy_snapshot &lt;- h15_long |&gt;
  filter(
    date %in% ymd(c("2026-09-16", "2026-09-17")),
    str_detect(
      instruments,
      "Federal funds \\(effective\\)|Bank prime loan"
    )
  ) |&gt;
  mutate(
    series = if_else(
      str_detect(instruments, "Federal funds"),
      "Effective federal funds rate",
      "Bank prime rate"
    )
  ) |&gt;
  select(date, series, rate) |&gt;
  arrange(series, date)

if (nrow(policy_snapshot) != 4 || anyNA(policy_snapshot$rate)) {
  stop(
    paste0(
      "The four required H.15 observations were not recovered. ",
      "Use the dated h15_2026-09-21.html snapshot."
    )
  )
}

# Freddie Mac PMMS ------------------------------------------------------
pmms_page &lt;- read_cached_page(
  "https://www.freddiemac.com/pmms/archive",
  "pmms_2026-09-21.html"
)

pmms_dates &lt;- pmms_page |&gt;
  html_elements("p.lead strong") |&gt;
  html_text2() |&gt;
  str_squish() |&gt;
  mdy(locale = "C", quiet = TRUE)

pmms_tables &lt;- pmms_page |&gt;
  html_elements("table.hover") |&gt;
  html_table(fill = TRUE)

if (
  length(pmms_dates) == 0 ||
  length(pmms_dates) != length(pmms_tables) ||
  anyNA(pmms_dates)
) {
  stop("Freddie Mac dates and tables could not be matched reliably.")
}

pmms &lt;- map2_dfr(pmms_dates, pmms_tables, function(obs_date, tab) {
  clean_tab &lt;- clean_names(tab)

  if (!all(c("x30_yr_frm", "x15_yr_frm") %in% names(clean_tab))) {
    stop("Expected PMMS mortgage-rate columns were not found.")
  }

  clean_tab |&gt;
    transmute(
      date = as_date(obs_date),
      mortgage_30y = percent_to_decimal(x30_yr_frm),
      mortgage_15y = percent_to_decimal(x15_yr_frm)
    )
}) |&gt;
  filter(is.finite(mortgage_30y), is.finite(mortgage_15y)) |&gt;
  distinct(date, .keep_all = TRUE) |&gt;
  arrange(date)

analysis_rates &lt;- pmms |&gt;
  filter(date %in% ymd(c("2026-09-10", "2026-09-17"))) |&gt;
  arrange(date)

if (nrow(analysis_rates) != 2 || anyNA(analysis_rates$mortgage_30y)) {
  stop(
    paste0(
      "The September 10 and September 17 PMMS observations were not both found. ",
      "Use the dated pmms_2026-09-21.html snapshot."
    )
  )
}

# Census New Residential Sales -----------------------------------------
census_page &lt;- read_cached_page(
  "https://www.census.gov/construction/nrs/current/index.html",
  "census_nrs_2026-09-21.html"
)

census_text &lt;- census_page |&gt;
  html_element("body") |&gt;
  html_text2() |&gt;
  str_squish()

median_price_match &lt;- str_match(
  census_text,
  regex(
    "median sales price[^$]{0,250}\\$([0-9,]+)",
    ignore_case = TRUE
  )
)

median_price &lt;- parse_number(median_price_match[1, 2])

if (
  !is.finite(median_price) ||
  median_price &lt;= 0 ||
  !str_detect(census_text, regex("July 2026", ignore_case = TRUE))
) {
  stop(
    "The July 2026 Census median sales price was not extracted reliably."
  )
}

# Save complete cleaned data and the exact analysis subsets ------------
# These CSV files are written to data/ at the repository root so that
# every dataset used downstream can be inspected without rerunning R.
fomc_statement &lt;- tibble(
  event_date = ymd("2026-09-16"),
  source = "Federal Reserve FOMC statement",
  statement_text = fomc_text
)

write_csv(fomc_statement, file.path(data_dir, "fomc_statement.csv"))
write_csv(h15_long, file.path(data_dir, "h15_clean_full.csv"))
write_csv(pmms, file.path(data_dir, "pmms_clean_full.csv"))
write_csv(policy_snapshot, file.path(data_dir, "policy_snapshot.csv"))
write_csv(analysis_rates, file.path(data_dir, "analysis_mortgage_rates.csv"))

census_snapshot &lt;- tibble(
  snapshot_date = ymd("2026-09-21"),
  reference_month = ymd("2026-07-01"),
  median_new_home_price = median_price
)
write_csv(census_snapshot, file.path(data_dir, "census_price_snapshot.csv"))


The raw webpages contain dates embedded in headings, interest rates stored as character strings with percent signs, and the Census price embedded in prose. Cleaning therefore changes representation, not economic meaning: 6.95% becomes 0.0695 for calculation, comma-separated dollar text becomes a number, and the dated columns in H.15 become a tidy date-series-rate table. The validation checks deliberately stop the render rather than silently produce a chart from incomplete observations.


Show the reproducible R code
rate_previous_week &lt;- analysis_rates$mortgage_30y[[1]]
rate_fomc_week &lt;- analysis_rates$mortgage_30y[[2]]
rate_change_bp &lt;- (rate_fomc_week - rate_previous_week) * 10000

effr_before &lt;- policy_snapshot |&gt;
  filter(
    series == "Effective federal funds rate",
    date == ymd("2026-09-16")
  ) |&gt;
  pull(rate)

effr_after &lt;- policy_snapshot |&gt;
  filter(
    series == "Effective federal funds rate",
    date == ymd("2026-09-17")
  ) |&gt;
  pull(rate)

prime_before &lt;- policy_snapshot |&gt;
  filter(series == "Bank prime rate", date == ymd("2026-09-16")) |&gt;
  pull(rate)

prime_after &lt;- policy_snapshot |&gt;
  filter(series == "Bank prime rate", date == ymd("2026-09-17")) |&gt;
  pull(rate)

median_loan &lt;- 0.80 * median_price
payment_previous_week &lt;- mortgage_payment(median_loan, rate_previous_week)
payment_fomc_week &lt;- mortgage_payment(median_loan, rate_fomc_week)
monthly_payment_change &lt;- payment_fomc_week - payment_previous_week
annual_payment_change &lt;- 12 * monthly_payment_change
payment_change_pct &lt;- payment_fomc_week / payment_previous_week - 1

previous_week_label &lt;- paste0(
  "Previous week: ", percent(rate_previous_week, accuracy = 0.01)
)
fomc_week_label &lt;- paste0(
  "FOMC week: ", percent(rate_fomc_week, accuracy = 0.01)
)

result_summary &lt;- tibble(
  Measure = c(
    "Effective federal-funds rate",
    "Bank prime rate",
    "30-year fixed mortgage rate"
  ),
  `Earlier observation` = c(
    effr_before, prime_before, rate_previous_week
  ),
  `Later observation` = c(
    effr_after, prime_after, rate_fomc_week
  ),
  `Change (basis points)` = 10000 *
    (`Later observation` - `Earlier observation`),
  Timing = c(
    "Sep. 16 to Sep. 17 (daily)",
    "Sep. 16 to Sep. 17 (daily)",
    "Sep. 10 PMMS to Sep. 17 PMMS"
  )
)




Show the reproducible R code
result_summary |&gt;
  mutate(
    `Earlier observation` = percent(`Earlier observation`, accuracy = 0.01),
    `Later observation` = percent(`Later observation`, accuracy = 0.01),
    `Change (basis points)` = round(`Change (basis points)`)
  ) |&gt;
  knitr::kable(align = c("l", "r", "r", "r", "l"))




